template <class... Ts> struct overload : Ts... { using Ts::operator()...; };
using Shape = std::variant<Circle, Square>;

std::string collide(const Shape &a, const Shape &b) {
    return std::visit(overload{
        [](const Circle &c, const Square &s) { return "circle vs square"; },
        [](const Square &s, const Circle &c) { return collide(c, s); },   // canonicalise
        [](const auto &, const auto &)       { return std::string{"same kind"}; },
    }, a, b);
}

struct ShapeVisitor {
    virtual void visit(const Circle &) = 0;
    virtual void visit(const Square &) = 0;
};
struct Shape { virtual void accept(ShapeVisitor &v) const = 0; };
struct Circle : Shape {
    double radius;
    void accept(ShapeVisitor &v) const override { v.visit(*this); }   // dispatch #2 target
};
// collide(a, b): ColliderVisitor v{b}; a.accept(v);   (second accept inside visit())

using Key = std::pair<std::type_index, std::type_index>;
using Handler = std::function<void(const Shape &, const Shape &)>;
std::unordered_map<Key, Handler> handlers;
handlers[{typeid(Circle), typeid(Square)}] = [](const Shape &a, const Shape &b) { /* ... */ };

void collide(const Shape &a, const Shape &b) {
    auto it = handlers.find({typeid(a), typeid(b)});
    if (it == handlers.end()) throw std::runtime_error("unhandled shape pair");
    it->second(a, b);
}
